<?php  namespace qqworld_collector\module; use qqworld_collector\lib; class pseudo_original extends lib { var $options; var $module = 'pseudo-original'; var $log_id = 'pseudo-original'; var $settings_name = 'qqworld-collector-pseudo-original'; var $artificial_intelligence; var $replacement_keywords; var $rewrite_title; var $api; var $random_paragraphs; var $originality_detection; var $seo_cheater; var $simulate_manual_publish; var $suggestion_paragraphs; var $long_tail_keywords; public function __construct() { if ( !apply_filters( 'qqworld-collector-activated', false ) ) return; if ( apply_filters( 'qqworld-collector-activated-license', false ) && !apply_filters( 'qqworld-collector-activated-module-' . $this->module, false ) ) return; add_action( 'admin_menu', array($this, 'admin_menu') ); add_action( 'admin_init', array($this, 'register_settings') ); add_action( 'admin_enqueue_scripts', array($this, 'admin_enqueue_scripts') ); add_filter( 'qqworld-collector-script-translation-array', array($this, 'add_translation_array') ); add_action( 'init', array($this, 'load_libs' ) ); add_filter( 'qqworld-collector-pseudo-original-get-ai-apis', array($this, 'get_ai_apis') ); add_action( 'qqworld-collector-settings-meta-box', array($this, 'setting_meta_box') ); if ( apply_filters( 'qqworld-collector-activated-module-' . $this->module, false) ) add_filter( 'qqworld-collector-sdks', array($this, 'external_sdk') ); } public function get_ai_apis($apis=[]) { return array( 'deepseek' => __('DeepSeek Chat', $this->text_domain), 'siliconflow' => __('Silicon Flow', $this->text_domain), 'qianfan' => __('Baidu Qianfan', $this->text_domain), 'bailian' => __('Aliyun Bailian', $this->text_domain), 'doubao' => __('ByteDance - Doubao', $this->text_domain), 'xfyun' => __('Xinghuo Cognitive Model', $this->text_domain), 'chatgpt' => 'ChatGPT', 'custom' => __('Custom API', $this->text_domain) ); } public function load_libs() { if (!apply_filters( 'qqworld-collector-activated-module-' . $this->modu